mapper.select:
SELECT atr.ARTICLE_VERSION_ID AS articleId, t.NAME AS tagName FROM article_version_tag_relation atr INNER JOIN tag t ON t.ID = atr.TAG_ID WHERE atr.ARTICLE_VERSION_ID IN
#{articleVersionId}
ORDER BY atr.ARTICLE_VERSION_ID, atr.TAG_ID

SELECT air.ARTICLE_VERSION_ID AS articleId, air.ARTICLE_IMAGE AS coverImage FROM article_version_image_relation air WHERE air.ARTICLE_VERSION_ID IN
#{articleVersionId}
ORDER BY air.ARTICLE_VERSION_ID, air.ARTICLE_IMAGE
